beforeExample:
class Example {
    public void check(String text, String search) {
        if (text.indexOf(search) >= 0) {
            System.out.println("Found: " + search);
        }
    }
}

afterExample:
class Example {
    public void check(String text, String search) {
        if (text.contains(search)) {
            System.out.println("Found: " + search);
        }
    }
}

